#include <cstdio>
using namespace std;
int a[1010];
int dp[10010];
const int MOD = 1e9 + 7;
int main() {
    int n, w;
    scanf("%d%d", &n, &w);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    // dp[i][j]: 用i种纸币凑出金额j的种数
    dp[0] = 1;
    for (int i = 0; i < n; i++) { // 当前只有x种纸币, 构造所有可能的金额 
        for (int j = a[i]; j <= w; j++) {
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD;
        }
    }
    printf("%d\n", dp[w]);
    return 0;
}
